typedef struct {
    char *key;
    int value;
} HashEntry;

typedef struct {
    HashEntry **buckets;
    size_t size;
} HashTable;

// Function to insert a key-value pair into the hash table
void insert(HashTable *ht, const char *key, int value) {
    size_t index = hash_function(key) % ht->size;
    HashEntry *new_entry = malloc(sizeof(HashEntry));
    new_entry->key = strdup(key);
    new_entry->value = value;
    ht->buckets[index] = new_entry; // Overwrites existing entry without chaining
}

// Function to retrieve value by key
int get_value(HashTable *ht, const char *key) {
    size_t index = hash_function(key) % ht->size;
    HashEntry *entry = ht->buckets[index];
    if (entry && strcmp(entry->key, key) == 0) {
        return entry->value;
    }
    // Handle missing key case
    return -1; // Indicates not found
}
